package com.optarena.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Map;
import org.springframework.web.bind.annotation.*;

@RestController
public class PricingController {

    @GetMapping("/price")
    public Map<String, Double> price(@RequestParam double amount, @RequestParam double taxRate) {
        double total = amount * (1 + taxRate);
        BigDecimal rounded = BigDecimal.valueOf(total).setScale(2, RoundingMode.HALF_UP);
        return Map.of("total", rounded.doubleValue());
    }
}
